aos_model_eval_issuer_private.initialize.body:
BEGIN
     PERFORM 1 FROM aos_model_eval_issuer_private.issuer_epoch
       WHERE org_id=NEW.org_id AND project_id=NEW.project_id
         AND issuer_id=NEW.issuer_id AND key_id=NEW.key_id AND root_hash IS NOT NULL FOR SHARE;
     IF NOT FOUND THEN
       RAISE EXCEPTION 'MODEL_CERTIFICATE_ACTIVE_ROOT_HEAD_MISSING' USING ERRCODE='42501';
     END IF;
     INSERT INTO aos_model_eval_issuer_private.certificate_epoch(org_id,project_id,certificate_hash,epoch,active_hash)
       VALUES(NEW.org_id,NEW.project_id,NEW.content_hash,1,NEW.content_hash);
     RETURN NULL;
     END

public.aip_budget_cost_fence_guard_a0v_1.body:
BEGIN
     IF TG_OP='INSERT' THEN
       IF session_user<>'aos_budget_consumer_call' OR current_user<>'aos_budget_consumer_owner' OR NEW.version<>1 THEN
         RAISE EXCEPTION 'BUDGET_COST_FENCE_CONSUMER_REQUIRED' USING ERRCODE='42501'; END IF;
     ELSIF TG_OP='UPDATE' THEN
       IF (NEW.org_id,NEW.project_id,NEW.budget_id,NEW.revision,NEW.decision_id) IS DISTINCT FROM
          (OLD.org_id,OLD.project_id,OLD.budget_id,OLD.revision,OLD.decision_id) OR NEW.version<>OLD.version+1 THEN
         RAISE EXCEPTION 'BUDGET_COST_FENCE_DRIFT' USING ERRCODE='23514'; END IF;
     ELSE RAISE EXCEPTION 'BUDGET_COST_FENCE_HISTORY_REQUIRED'; END IF;
     RETURN NEW; END

public.binding_evaluator_read_lock_only_.body:
BEGIN
       IF current_user='aos_aip_binding_evaluator' OR session_user='aos_aip_binding_evaluator' THEN
         RAISE EXCEPTION 'BINDING_EVALUATOR_READ_LOCK_ONLY' USING ERRCODE='42501';
       END IF;
       IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
     END
